        "tier": 5,
        "title": "Campuses are full of tunnels and grates by design",
        "body": "Utility corridors, steam tunnels, and access hatches are normal. Conspiracy method treats normal infrastructure as assassin props. Without residue, access logs, or ballistic support, the hatch is just a hatch.\n\nLarge universities maintain service routes for HVAC, IT, and facilities. Their existence is not a clue. A subterranean hit theory must show that a specific path was used that day and that the wound geometry matches a shot from below — neither of which Owens’s early tunnel speculation supplied.",
