        "body": "Contemporary coverage quoted her saying she was theorizing. That honesty did not stop the clip economy from treating it as a lead. Later she largely replaced tunnels with foreign planes, freemasons, and mic bombs — a pattern of rotating mechanisms rather than converging on one proven one.\n\nRotation without convergence is the opposite of investigation. Track the catalog: if each mechanism is abandoned without a published kill criterion, the audience is being trained on novelty, not truth procedures.",
