        "tier": 5,
        "title": "How to dismantle the “maroon folder” talking point in practice",
        "body": "Ask for the operational definition of a decoy: who tasked them, what their job was, how they coordinated with the shot, and what evidence shows that beyond shirt color. If the answer is only a Google Drive of similarly dressed men, you are looking at a scrapbook, not a counterintelligence product.",
