        "title": "The death on camera is a political assassination by gunshot presentation, not a lodge ceremony",
        "body": "Ritual claims need more than aesthetic. Cameras show a speech and a shot. Re-skinning that as freemason ritual is commentary, not reconstruction.\n\nPrimary media is hard to gaslight for long because thousands of people can pause the same frames. If a theory needs you to not trust your ears on a gunshot, or to invent a blast that is not on screen, the theory is asking for faith against the recording rather than offering a better reading of it. A strong alternate reconstruction would slow the tape down, mark timestamps across angles, and show why every independent camera is misleading in the same way. That work is almost never done in the clip economy — for a reason.",
