        "body": "After-action failure is not intentional set-up. Protection is probabilistic; determined elevated shooters sometimes win. Ugly outcomes produce ugly optics.\n\nOptics are not wiretaps. Keep professional criticism of roof ownership and site surveys separate from homicide accusations. If you allege intentional stand-down, produce the order or the payment.",
        "sources": []
