        "tier": 5,
        "title": "Why this claim is more serious than vague foreign fog",
        "body": "This claim is more serious than vague foreign fog because it names a living person in a murder-plot role. Named accusations require higher discipline, not looser vibes.\n\nForeign fog can fail quietly. A named protector plot fails into defamation and reputational harm. That seriousness is why itinerary collisions and missing meeting records matter more here than on anonymous Legion lore.",
