        "body": "Line of sight from elevation means someone failed to own that space. Failure can be budget, competence, time, or attacker skill. Conspiracy requires intent evidence. Those are different moral and legal universes.\n\nProtection is a probabilistic business. Even excellent details lose sometimes against a determined elevated shooter with initiative. Losses produce ugly optics. Optics are not wiretaps. Keep professional criticism of site surveys and roof ownership separate from homicide accusations against named protectors.\n\nA clean standard: if you allege intentional stand-down, produce the order or the payment. If you only have a list of best practices that were missed, you have a negligence debate — still serious, still not “they ran the hit.”",
